public OrderDto getOrder(String orderId) {
    // Дефект: синхронный HTTP вызов обратно в order-service
    return restTemplate.getForObject("http://order-service/api/v1/orders/" + orderId, OrderDto.class);
}

@DeleteMapping("/api/v1/orders/{id}/force")
fun forceDeleteOrder(@PathVariable id: String): ResponseEntity<Void> {
    orderRepository.deleteById(id)
    return ResponseEntity.noContent().build()
}
